      if ((side === 'base' && file.status === 'added') || (side === 'head' && file.status === 'removed')) continue;
      const source = snapshot.sources[file[`${side}_source`]];
      requireReceipt(source && source.ref === pr[side].sha &&
        source.path === (side === 'base' ? live.previous_filename || file.path : file.path),
      'changed-file evidence omitted or substituted');
    }
  }
}

module.exports = {DOMAIN, MAX_RECEIPT_BYTES, validateTrust, reviewDecision, issueReceipt, verifySignedRecord, verifyReceipt, marker, loadReceipt, verifySources};

import assert from 'node:assert/strict';

// Consumers pass their parsed real workflow and GitHub's expression evaluator.
export function assertFrozenWorkflow(workflow, evaluate) {
  const resolver = workflow.jobs['resolve-clouseau'];
  assert.ok(resolver, 'one isolated resolver job is required');
  assert.deepEqual(resolver.permissions, {contents: 'read'});
  assert.equal(resolver.steps.length, 1);
  assert.match(resolver.steps[0].uses, /^gaulatti\/clouseau\/scripts\/resolve@[a-f0-9]{40}$/);
  assert.equal(resolver.steps[0].with, undefined, 'contributors cannot configure a source');
  assert.equal(resolver.outputs.sha, '${{ steps.engine.outputs.sha }}');
  assert.equal(resolver.outputs.digest, '${{ steps.engine.outputs.digest }}');
  const original = {sha: 'a'.repeat(40), digest: 'c'.repeat(64)};
  const next = {sha: 'b'.repeat(40), digest: 'd'.repeat(64)};
  let count = 0;
  for (const [name, job] of Object.entries(workflow.jobs)) {
    const checkouts = job.steps?.filter(step => step.with?.repository === 'gaulatti/clouseau' || step.with?.path === '.clouseau-ci') || [];
    const checkout = checkouts[0];
    const actions = job.steps?.filter(step => step.uses === './.clouseau-ci') || [];
    if (!checkout && !actions.length) continue;
    count++;
    assert.ok(checkout, name);
    assert.equal(checkouts.length, 1, `${name} cannot overwrite the frozen engine`);
    assert.equal(checkout.with.repository, 'gaulatti/clouseau', `${name} uses the authorized repository`);
    const needs = Array.isArray(job.needs) ? job.needs : [job.needs];
    assert.ok(needs.includes('resolve-clouseau'), `${name} directly consumes the one selection`);
    assert.equal(checkout.with.ref, "${{ needs.resolve-clouseau.outputs.sha || '0000000000000000000000000000000000000000' }}");
    assert.equal(checkout.with['persist-credentials'], false);
    assert.equal(checkout.with.path, '.clouseau-ci');
    assert.ok(!JSON.stringify(job).includes('gaulatti/clouseau@'), `${name} cannot mix pinned engines`);
    for (const [selected, currentMain] of [[original, next], [next, next]]) {
      const context = {needs: {'resolve-clouseau': {result: 'success', outputs: selected}},
        github: {event_name: 'pull_request_target', event: {pull_request: {body: currentMain.sha, head: {sha: currentMain.sha}}}}};
      assert.equal(evaluate(checkout.with.ref, context).coerceString(), selected.sha, name);
      assert.equal(evaluate(job.env.CLOUSEAU_ENGINE_SHA, context).coerceString(), selected.sha, name);
      assert.equal(evaluate(job.env.CLOUSEAU_ENGINE_DIGEST, context).coerceString(), selected.digest, name);
    }
    const failure = {needs: {'resolve-clouseau': {result: 'failure', outputs: {}}}, github: {event_name: 'pull_request_target'}};
    assert.equal(evaluate(checkout.with.ref, failure).coerceString(), '0'.repeat(40), `${name} has no stale fallback`);
    for (const action of actions) assert.ok(job.steps.indexOf(checkout) < job.steps.indexOf(action), name);
  }
  assert.ok(count >= 2, 'multiple engine stages must be checked');
}

'use strict';
const fs = require('node:fs');
const path = require('node:path');
const crypto = require('node:crypto');
const {digest} = require('./acceptance.cjs');

function engineDigest(root = path.join(__dirname, '..')) {
  const entries = [];
  function visit(relative) {
    const filename = path.join(root, relative);
    const stat = fs.lstatSync(filename);
    if (stat.isSymbolicLink()) throw new Error('Review engine source cannot contain symbolic links');
    if (stat.isDirectory()) {
      for (const name of fs.readdirSync(filename).sort()) {
        if (name === '__pycache__' || /\.(test|spec)\.[cm]?js$/.test(name) || /^test_.*\.py$/.test(name)) continue;
        visit(path.join(relative, name));
      }
    } else {
      entries.push([relative.split(path.sep).join('/'), stat.mode & 0o111,
        crypto.createHash('sha256').update(fs.readFileSync(filename)).digest('hex')]);
    }
  }
  for (const relative of ['action.yml', 'src', 'policy', 'bin', 'skills', 'scripts']) visit(relative);
  return digest(entries);
}
module.exports = {engineDigest};

'use strict';

const LOCATIONS = ['.github/CODEOWNERS', 'CODEOWNERS', 'docs/CODEOWNERS'];
const user = /^[a-zA-Z0-9][a-zA-Z0-9-]{0,38}$/;

function pattern(value) {
  if (!value || /[!\[\]\\\0]/.test(value) || value.includes('***')) throw new Error('Unsupported CODEOWNERS pattern; manual ownership verification required');
  const rooted = value.startsWith('/');
  const directory = value.endsWith('/');
  const input = value.replace(/^\//, '').replace(/\/$/, '');
  // https://docs.github.com/en/repositories/managing-your-repositorys-settings-and-features/customizing-your-repository/about-code-owners
  // GitHub documents docs/* as non-recursive. Other terminal prefix globs
  // may refer to directories; do not fall through to a broader owner rule.
  if (!directory && /[*?]$/.test(input) && !['*', '**'].includes(input.split('/').at(-1))) throw new Error('Ambiguous CODEOWNERS prefix glob; manual ownership verification required');
  let expression = '';
  for (let i = 0; i < input.length; i++) {
    if (input.slice(i, i + 3) === '**/') { expression += '(?:.*/)?'; i += 2; }
    else if (input.slice(i, i + 2) === '**') { expression += '.*'; i++; }
    else if (input[i] === '*') expression += '[^/]*';
    else if (input[i] === '?') expression += '[^/]';
    else expression += input[i].replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
  }
  return new RegExp((rooted || input.includes('/') ? '^' : '(?:^|/)') + expression +
    (directory ? '/.*$' : /[*?]$/.test(input) ? '$' : '(?:/.*)?$'));
}

function parse(text) {
  if (typeof text !== 'string' || Buffer.byteLength(text) >= 3000000) throw new Error('CODEOWNERS is missing or oversized');
  const entries = [];
  for (const raw of text.split(/\r?\n/)) {
    const line = raw.replace(/#.*/, '').trim();
    if (!line) continue;
    const [glob, ...owners] = line.split(/\s+/);
    if (owners.some(owner => !/^@[a-zA-Z0-9][a-zA-Z0-9-]{0,38}(?:\/[a-zA-Z0-9_-]+)?$/.test(owner))) {
      throw new Error('Unverifiable CODEOWNERS identity; use GitHub usernames or teams');
    }
    entries.push({pattern: pattern(glob), owners});
  }
  return entries;
}

async function owns(github, repo, login, owners) {
  if (!user.test(login || '')) return false;
  const {data} = await github.rest.repos.getCollaboratorPermissionLevel({...repo, username: login});
  if (!['admin', 'maintain', 'write'].includes(data.permission)) return false;
  for (const owner of owners) {
    if (owner.toLowerCase() === `@${login}`.toLowerCase()) return true;
    const team = /^@([^/]+)\/(.+)$/.exec(owner);
    if (team && team[1].toLowerCase() === repo.owner.toLowerCase()) {
      const args = {org: team[1], team_slug: team[2], owner: repo.owner, repo: repo.repo};
      const {data: permission} = await github.rest.teams.checkPermissionsForRepoInOrg(args);
      if (permission.permissions?.push !== true) continue;
      const {data: membership} = await github.rest.teams.getMembershipForUserInOrg({org: team[1], team_slug: team[2], username: login});
      if (membership.state === 'active') return true;
    }
  }
  return false;
}

async function authority({github, repo, pr, files}) {
  try {
    let content;
    let location;
    for (const path of LOCATIONS) {
      try {
        const {data} = await github.rest.repos.getContent({...repo, path, ref: pr.base.sha});
        if (data.encoding !== 'base64' || typeof data.content !== 'string' || data.size >= 3000000) throw new Error('Incomplete CODEOWNERS source');
        content = new TextDecoder('utf-8', {fatal: true}).decode(Buffer.from(data.content, 'base64'));
        location = path; break;
      } catch (error) { if (error.status !== 404) throw error; }
    }
    if (content === undefined) return {automatic: true, configured: false, groups: [], base_sha: pr.base.sha,
      reason: 'No CODEOWNERS exists on the protected base; the optional code-owner gate is inactive.'};
    if (!files.length || files.length !== pr.changed_files) throw new Error('Incomplete ownership path inventory');
    const entries = parse(content);
    const paths = [...new Set(files.flatMap(file => file.previous_filename ? [file.previous_filename, file.filename] : [file.filename]))];
    const groups = paths.map(path => ({path, owners: entries.filter(entry => entry.pattern.test(path)).at(-1)?.owners || []}));
    const owner = pr.user?.type === 'User' && groups.every(group => group.owners.length);
    let automatic = Boolean(owner);
    if (automatic) for (const group of groups) if (!await owns(github, repo, pr.user.login, group.owners)) {automatic = false; break;}
    return {automatic, groups, location, base_sha: pr.base.sha,
      reason: automatic ? 'The PR author owns every affected path on the protected base.' : 'A code owner must approve this exact revision and merge manually; automatic merge is disabled.'};
  } catch (error) { return {automatic: false, groups: [], reason: `Automatic merge denied: ${error.message}`}; }
}

async function approved({github, repo, pr, ownership}) {
  if (!ownership.groups.length || ownership.groups.some(group => !group.owners.length)) return false;
  const reviews = await github.paginate(github.rest.pulls.listReviews, {...repo, pull_number: pr.number, per_page: 100});
  const latest = new Map();
  for (const review of reviews) if (review.user?.type === 'User' && review.user.login !== pr.user.login && review.state !== 'COMMENTED') latest.set(review.user.login, review);
  const accepted = [...latest.values()].filter(review => review.state === 'APPROVED' && review.commit_id === pr.head.sha);
  for (const group of ownership.groups) {
    let covered = false;
    for (const review of accepted) {
      try { if (await owns(github, repo, review.user.login, group.owners)) {covered = true; break;} } catch { /* Unverifiable membership grants no authority. */ }
    }
    if (!covered) return false;
  }
  return true;
}

module.exports = {pattern, parse, owns, authority, approved};

'use strict';

async function assertMergeProtection({github, repo, baseBranch, manual, privateOwnerAutomatic = false, assertProtection}) {
  const {data: settings} = await github.rest.repos.get(repo);
  const {data: branch} = await github.rest.repos.getBranch({...repo, branch: baseBranch});
  if (manual) {
    if (settings.allow_auto_merge !== false) throw new Error('Manual merge mode requires repository auto-merge to be disabled');
    try {
      await assertProtection();
    } catch (error) {
      if (!(settings.private === true && branch.protected === false && error.status === 403 &&
          /Upgrade to GitHub Pro or make this repository public/i.test(error.message))) throw error;
      return {enforced: false, reason: 'GitHub cannot enforce protection on this private plan. Tests and review passed independently; every merge remains manual.'};
    }
    if (branch.protected !== true) throw new Error('Available branch protection must be enabled before manual-mode approval');
    return {enforced: true};
  }
  if (privateOwnerAutomatic && settings.private === true && branch.protected === false && settings.allow_auto_merge === false) {
    try { await assertProtection(); } catch (error) {
      if (!(error.status === 403 && /Upgrade to GitHub Pro or make this repository public/i.test(error.message))) throw error;
      return {enforced: false, controllerManaged: true, reason: 'Private-plan branch protection is unavailable; explicit code-owner work alone may use the controller-enforced atomic acceptance path.'};
    }
    throw new Error('Available branch protection must be enabled before automatic approval');
  }
  if (!settings.allow_auto_merge || !branch.protected) throw new Error('Repository auto-merge and main protection must be enabled');
  await assertProtection();
  return {enforced: true};
}

module.exports = {assertMergeProtection};

'use strict';

// An exact-head/base transaction for the narrow private-plan exception only.
// Callers must first validate the acceptance record and all technical gates.
async function finalizePrivateOwner({github, repo, pr, assessment, baseBranch, verify}) {
